CREATE TABLE public.live_followup_settings(id boolean PRIMARY KEY DEFAULT true,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT live_followup_singleton CHECK(id));
GRANT SELECT ON public.live_followup_settings TO authenticated;
GRANT ALL ON public.live_followup_settings TO service_role;
ALTER TABLE public.live_followup_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY live_followup_settings_staff ON public.live_followup_settings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_module_access(auth.uid(),'events'));
CREATE OR REPLACE FUNCTION public.live_followup_enabled(p_event_id uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT (value->>'enabled')::boolean FROM live_followup_settings WHERE id),false) AND (p_event_id IS NULL OR coalesce((SELECT live_followup_enabled FROM events WHERE id=p_event_id),false)) $$;
REVOKE ALL ON FUNCTION public.live_followup_enabled(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_enabled(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.live_followup_source_contexts(p_limit integer DEFAULT 50) RETURNS TABLE(source_key text,changed_at timestamptz,context jsonb) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT s.source_key,s.changed_at,jsonb_build_object('event',jsonb_build_object('id',e.id,'live_followup_enabled',e.live_followup_enabled,'whatsapp_number_id',e.whatsapp_number_id,'self_service_slug',e.self_service_slug),'order',CASE WHEN o.id IS NULL THEN NULL ELSE jsonb_build_object('id',o.id,'created_at',o.created_at,'registered_at',o.registered_at,'origin',o.origin,'attribution',o.attribution,'is_paid',o.is_paid,'paid_externally',o.paid_externally,'stage',o.stage,'merged_into_order_id',o.merged_into_order_id,'products',o.products,'selfservice_cart_sent_at',o.selfservice_cart_sent_at) END,'access',CASE WHEN a.id IS NULL THEN NULL ELSE jsonb_build_object('id',a.id,'created_at',a.created_at,'registered_at',a.registered_at,'whatsapp_confirmed_at',a.whatsapp_confirmed_at,'entered_phone',a.entered_phone,'confirmed_phone',a.confirmed_phone,'instagram',a.instagram) END,'registration',CASE WHEN r.id IS NULL THEN NULL ELSE jsonb_build_object('full_name',r.full_name,'whatsapp',r.whatsapp) END,'customer',jsonb_build_object('whatsapp',c.whatsapp,'full_name',c.full_name,'instagram_handle',c.instagram_handle),'first_item_at',o.created_at,'cart_sent_at',q.sent_at,'paid_same_day',EXISTS(SELECT 1 FROM orders p WHERE p.event_id=o.event_id AND p.customer_id=o.customer_id AND (p.is_paid OR p.paid_externally) AND (p.paid_at AT TIME ZONE 'America/Sao_Paulo')::date=(o.created_at AT TIME ZONE 'America/Sao_Paulo')::date),'ig_instance_id',ig.whatsapp_number_id)
 FROM (SELECT * FROM live_followup_sources ORDER BY changed_at,source_key LIMIT least(greatest(p_limit,1),100)) s JOIN events e ON e.id=s.event_id
 LEFT JOIN orders o ON o.id=s.order_id
 LEFT JOIN LATERAL (SELECT * FROM live_selfservice_accesses aa WHERE aa.event_id=s.event_id AND (aa.id=s.access_id OR (s.access_id IS NULL AND s.order_id=ANY(aa.order_ids))) ORDER BY aa.created_at DESC LIMIT 1) a ON true
 LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN customer_registrations r ON r.order_id=o.id
 LEFT JOIN LATERAL (SELECT sent_at FROM selfservice_message_queue WHERE order_id=o.id AND kind='cart_link' AND status='sent' ORDER BY sent_at LIMIT 1) q ON true
 LEFT JOIN LATERAL (SELECT m.whatsapp_number_id FROM instagram_user_links l JOIN whatsapp_messages m ON m.phone=l.ig_user_id AND m.channel='instagram' AND m.direction='incoming' WHERE lower(l.username)=lower(trim(both '@ ' from c.instagram_handle)) ORDER BY m.created_at DESC LIMIT 1) ig ON true
$$;
REVOKE ALL ON FUNCTION public.live_followup_source_contexts(integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_source_contexts(integer) TO service_role;
CREATE OR REPLACE FUNCTION public.live_followup_job_context(p_job_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT jsonb_build_object('global_enabled',public.live_followup_enabled(NULL),'type_enabled',coalesce((cfg.value->'types'->j.type->>'enabled')::boolean,false),'event',jsonb_build_object('id',e.id,'live_followup_enabled',e.live_followup_enabled,'whatsapp_number_id',e.whatsapp_number_id,'self_service_slug',e.self_service_slug),'order',CASE WHEN o.id IS NULL THEN NULL ELSE jsonb_build_object('id',o.id,'stage',o.stage,'is_paid',o.is_paid,'paid_externally',o.paid_externally,'registered_at',o.registered_at,'products',o.products,'merged_into_order_id',o.merged_into_order_id,'selfservice_cart_sent_at',o.selfservice_cart_sent_at,'cart_link',o.cart_link) END,'access',CASE WHEN a.id IS NULL THEN NULL ELSE jsonb_build_object('registered_at',a.registered_at,'whatsapp_confirmed_at',a.whatsapp_confirmed_at,'form_draft',a.form_draft) END,'registration',jsonb_build_object('full_name',r.full_name),'customer',jsonb_build_object('full_name',c.full_name),'number',jsonb_build_object('provider',n.provider,'is_active',n.is_active,'is_online',n.is_online),'instance',jsonb_build_object('last_message',i.last_message),'has_phone',length(regexp_replace(coalesce(r.whatsapp,c.whatsapp,a.confirmed_phone,a.entered_phone,''),'\D','','g'))>=10,'cart_sent_at',q.sent_at,
 'customer_replied',EXISTS(SELECT 1 FROM whatsapp_messages m WHERE m.phone IN (j.phone,j.phone||'@s.whatsapp.net',l.ig_user_id) AND m.direction='incoming' AND m.whatsapp_number_id=j.whatsapp_number_id AND m.created_at>coalesce(prev.sent_at,j.base_at)),
 'manual_recent',EXISTS(SELECT 1 FROM whatsapp_messages m WHERE m.phone IN (j.phone,j.phone||'@s.whatsapp.net',l.ig_user_id) AND m.whatsapp_number_id=j.whatsapp_number_id AND m.direction='outgoing' AND m.sender_user_id IS NOT NULL AND m.created_at>now()-interval '10 minutes'),
 'opted_out',EXISTS(SELECT 1 FROM automation_opt_outs b WHERE b.phone_key=automation_phone_key(j.phone)) OR EXISTS(SELECT 1 FROM blocked_contacts b WHERE right(regexp_replace(b.phone,'\D','','g'),8)=right(j.phone,8)) OR EXISTS(SELECT 1 FROM whatsapp_messages m WHERE m.phone IN (j.phone,j.phone||'@s.whatsapp.net',l.ig_user_id) AND m.direction='incoming' AND m.created_at>j.base_at AND lower(trim(m.message)) IN ('parar','sair','não quero','nao quero')),
 'window_open',EXISTS(SELECT 1 FROM whatsapp_messages m WHERE m.phone IN (j.phone,j.phone||'@s.whatsapp.net',l.ig_user_id) AND m.direction='incoming' AND m.whatsapp_number_id=j.whatsapp_number_id AND m.created_at>now()-interval '24 hours'))
 FROM live_followup_jobs j JOIN events e ON e.id=j.event_id LEFT JOIN live_followup_settings cfg ON cfg.id
 LEFT JOIN orders o ON o.id=j.order_id LEFT JOIN live_selfservice_accesses a ON a.id=j.access_id LEFT JOIN customer_registrations r ON r.order_id=o.id LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN whatsapp_numbers n ON n.id=j.whatsapp_number_id LEFT JOIN live_followup_instances i ON i.whatsapp_number_id=j.whatsapp_number_id
 LEFT JOIN instagram_user_links l ON lower(l.username)=j.instagram
 LEFT JOIN LATERAL (SELECT max(sent_at) sent_at FROM live_followup_jobs WHERE sequence_key=j.sequence_key AND step<j.step AND status='sent') prev ON true
 LEFT JOIN LATERAL (SELECT sent_at FROM selfservice_message_queue WHERE order_id=o.id AND kind='cart_link' AND status='sent' ORDER BY sent_at LIMIT 1) q ON true
 WHERE j.id=p_job_id
$$;
REVOKE ALL ON FUNCTION public.live_followup_job_context(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_job_context(uuid) TO service_role;
CREATE INDEX live_followup_access_order_lookup ON public.live_selfservice_accesses USING gin(order_ids);
CREATE INDEX live_followup_queue_order_sent ON public.selfservice_message_queue(order_id,sent_at) WHERE kind='cart_link' AND status='sent';
CREATE OR REPLACE FUNCTION public.live_followup_failure(p_job_id uuid,p_reason text,p_uncertain boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE j live_followup_jobs; BEGIN SELECT * INTO j FROM live_followup_jobs WHERE id=p_job_id AND status='processing' FOR UPDATE; IF NOT FOUND THEN RETURN; END IF;
 UPDATE live_followup_jobs SET status=CASE WHEN p_uncertain THEN 'uncertain' ELSE 'skipped' END,reason=left(p_reason,200) WHERE id=j.id;
 UPDATE live_followup_instances SET consecutive_errors=consecutive_errors+1,paused=paused OR p_uncertain OR consecutive_errors+1>=3 OR p_reason ~ '(disconnected|restrict|provider_429|provider_403)',reason=left(p_reason,200) WHERE whatsapp_number_id=j.whatsapp_number_id;
END $$;
REVOKE ALL ON FUNCTION public.live_followup_failure(uuid,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.live_followup_failure(uuid,text,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.live_followup_admin_summary(p_event_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
BEGIN IF NOT (has_role(auth.uid(),'admin') OR has_module_access(auth.uid(),'events')) THEN RAISE EXCEPTION 'Forbidden'; END IF;
RETURN jsonb_build_object('sent',coalesce((SELECT sum(sent) FROM live_followup_daily WHERE day=(now() AT TIME ZONE 'America/Sao_Paulo')::date AND (p_event_id IS NULL OR event_id=p_event_id)),0),'skipped',coalesce((SELECT sum(skipped) FROM live_followup_daily WHERE day=(now() AT TIME ZONE 'America/Sao_Paulo')::date AND (p_event_id IS NULL OR event_id=p_event_id)),0),'paid',coalesce((SELECT sum(paid) FROM live_followup_daily WHERE day=(now() AT TIME ZONE 'America/Sao_Paulo')::date AND (p_event_id IS NULL OR event_id=p_event_id)),0),'paused',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',i.whatsapp_number_id,'label',n.label,'reason',i.reason)),'[]'::jsonb) FROM live_followup_instances i JOIN whatsapp_numbers n ON n.id=i.whatsapp_number_id WHERE i.paused)); END $$;
REVOKE ALL ON FUNCTION public.live_followup_admin_summary(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.live_followup_admin_summary(uuid) TO authenticated,service_role;